def get_public_questions() -> List[Dict[str, Any]]:
    """
    Returns the 30 quiz questions for public frontend display,
    omitting internal role_ids from options to prevent client-side manipulation.
    """
    public_q = []
    for q in QUIZ_QUESTIONS:
        sec_info = SECTION_METADATA.get(q["section"], {"title_th": q["section"], "desc": ""})
        options = [
            {
                "id": opt["id"],
                "text": opt["text"],
            }
            for opt in q["options"]
        ]
        public_q.append({
            "id": q["id"],
            "section": q["section"],
            "section_th": sec_info["title_th"],
            "section_desc": sec_info["desc"],
            "question": q["question"],
            "is_multiple": q["is_multiple"],
            "options": options
        })
    return public_q


def evaluate_quiz(user_answers: Dict[str, Any]) -> Dict[str, Any]:
    """
    Evaluates the 30 answers against the BCS Tech Career Quiz mapping.
    Matches point distribution logic and returns ranked career suggestions.
    """
    scores = {role_id: 0 for role_id in ROLES_METADATA.keys()}
    q_map = {q["id"]: q for q in QUIZ_QUESTIONS}

    for q_str_id, chosen in user_answers.items():
        try:
            q_id = int(q_str_id)
        except (ValueError, TypeError):
            continue

        if q_id not in q_map:
            continue

        q = q_map[q_id]

        if q.get("is_multiple", False):
            if isinstance(chosen, list):
                for opt_id in chosen:
                    if 0 <= opt_id < len(q["options"]):
                        for r in q["options"][opt_id]["role_ids"]:
                            scores[r] += 1
        else:
            if isinstance(chosen, int) and 0 <= chosen < len(q["options"]):
                for r in q["options"][chosen]["role_ids"]:
                    scores[r] += 1

    candidate_roles = []
    for role_id, raw_score in scores.items():
        meta = ROLES_METADATA[role_id]
        max_s = ROLE_MAX_SCORES.get(role_id, 30)
        match_pct = round((raw_score / max_s) * 100) if max_s > 0 else 0
        candidate_roles.append((match_pct, raw_score, role_id, meta, max_s))

    # Sort descending by (match_percentage, raw_score)
    candidate_roles.sort(key=lambda x: (x[0], x[1]), reverse=True)

    results = []
    for rank, (match_pct, raw_score, role_id, meta, max_s) in enumerate(candidate_roles, 1):
        results.append({
            "rank": rank,
            "role_id": role_id,
            "title": meta["title"],
            "title_th": meta["title_th"],
            "category": meta["category"],
            "category_th": meta.get("category_th", meta["category"]),
            "badge_color": meta["badge_color"],
            "score": raw_score,
            "max_score": max_s,
            "match_percentage": match_pct,
            "summary": meta["summary"],
            "description": meta["description"],
            "key_skills": meta["key_skills"],
            "matching_ce_courses": meta["matching_ce_courses"],
            "career_prospects": meta["career_prospects"],
        })

    return {
        "success": True,
        "total_questions": len(QUIZ_QUESTIONS),
        "answered_count": len(user_answers),
        "top_roles": results[:3],
        "all_roles": results,
    }
